impl Status {
    pub fn as_str(self) -> &'static str {
        match self {
            Status::Off => "off",
            Status::Unauthorized => "unauthorized",
            Status::Queued => "queued",
            Status::Skipped => "skipped",
            Status::Ok => "ok",
            Status::Unavailable => "unavailable",
            Status::Timeout => "timeout",
            Status::Unparsable => "unparsable",
        }
    }
}

